#!/usr/bin/env python3
"""Inspect workspace and report.pdf structure before adding a cover page."""
import os
import sys

print("CWD:", os.getcwd())
print("\nDirectory listing:")
for name in sorted(os.listdir(".")):
    full = os.path.join(".", name)
    if os.path.isfile(full):
        print(f"  FILE  {name}  ({os.path.getsize(full)} bytes)")
    else:
        print(f"  DIR   {name}")

pdf_path = "report.pdf"
if not os.path.isfile(pdf_path):
    print(f"\nERROR: {pdf_path} not found.")
    sys.exit(1)

try:
    from pypdf import PdfReader
except ImportError:
    try:
        from PyPDF2 import PdfReader
    except ImportError as exc:
        print("ERROR: no pypdf/PyPDF2 available:", exc)
        sys.exit(1)

reader = PdfReader(pdf_path)
print(f"\nreport.pdf info:")
print("  page count:", len(reader.pages))
meta = reader.metadata
if meta:
    for key in ("title", "author", "subject", "creator", "producer"):
        print(f"  metadata {key}:", getattr(meta, key, None))
first = reader.pages[0]
mb = first.mediabox
print(f"  first page mediabox: {mb.width} x {mb.height} "
      f"(unit = PDF points; letter = 612 x 792)")

# Check libraries available for cover creation / merging
for lib in ("reportlab", "pypdf", "PyPDF2"):
    try:
        __import__(lib)
        print(f"  library available: {lib}")
    except ImportError:
        print(f"  library MISSING: {lib}")
